#include <stdio.h>
#define SQ(x)    ((x)*(x))
#define MAX(a,b) ((a)>(b)?(a):(b))

int main(void) {
    printf("%d %d\n", SQ(5), MAX(3, 7));
    printf("%d\n", SQ(2 + 3));      /* ((2+3)*(2+3)) = 25 */
    printf("%d\n", MAX(SQ(2), 3)); /* 宏可以嵌套调用 */
    return 0;
}

#include <stdio.h>

int sq(int x) { return x * x; }
#define TWICE(f) ((f) + (f))

int twice(int f) { return f + f; }

int main(void) {
    printf("%d\n", TWICE(sq(3)));   /* sq(3)+sq(3) = 18，sq 调用 2 次 */
    printf("%d\n", twice(sq(3)));   /* 9 + 9 = 18，sq 调用 1 次 */
    return 0;
}

