#include <stdio.h>
#define MMAX(a,b) ((a)>(b)?(a):(b))

int imax(int a, int b) { return a > b ? a : b; }

int main(void) {
    printf("%d %d\n", MMAX(3, 7), imax(3, 7));
    printf("%.1f\n", MMAX(3.9, 2.0));  /* 宏不限类型 */
    printf("%c\n", MMAX('a', 'b'));     /* 字符也可以 */
    return 0;
}

#include <stdio.h>
#define SWAP(a,b) do { int t = (a); (a) = (b); (b) = t; } while (0)

int main(void) {
    int x = 1, y = 2;
    if (x < y) SWAP(x, y);
    else printf("no\n");
    printf("%d %d\n", x, y);
    SWAP(x, y);
    printf("%d %d\n", x, y);
    return 0;
}

